  const unlocked=Boolean(workspace?.isEditingOwner&&workspace.lifecycle==='OPEN'&&!busy);const pageLocked=Boolean(workspace?.pagesInOrder.find(p=>p.pageLineageId===page?.pageLineageId)?.editLocked);const compositionAllowed=Boolean(unlocked&&workspace?.actions.find(a=>a.action==='COMPOSITION')?.allowed);
  const translate=(scope:Extract<WorkspaceCommand['operation'],{kind:'REQUEST_TRANSLATION'}>['payload']['scope'])=>run(async()=>{if(!page||!workspace?.settings)return;await send({kind:page.resultRevision==='0'?'REQUEST_TRANSLATION':'RETRANSLATE',payload:{pageId:page.pageLineageId,scope,expectedResultRevision:page.resultRevision,settingsVersion:workspace.settings.settingsVersion}});setNotice('처리를 접수했어요. 수행·결과·정산 상태를 각각 확인할 수 있어요.');});
  const hasBusy=Boolean(workspace?.requests.some(r=>!terminal(r.state)));const sameLanguage=Boolean(workspace?.settings&&workspace.settings.sourceLanguage===workspace.settings.targetLanguage);
  const uploadForView=pageUpload?pageUploads.current.get(pageUpload.prepare.commandId)??null:null;const visibleUpload=uploadForView&&isUploadCurrent(uploadForView)?pageUpload:null;const uploadMutationAllowed=Boolean(visibleUpload&&compositionAllowed&&workspace?.workspaceRevision===visibleUpload.prepare.target.expectedWorkspaceRevision);const newUploadAllowed=compositionAllowed&&canChooseUpload();
  const uploadRows=visibleUpload?[...visibleUpload.entries].sort((left,right)=>{const order=visibleUpload.preview?.candidateIdsInOrder??[],a=order.indexOf(left.candidateId),b=order.indexOf(right.candidateId);return a<0?b<0?0:1:b<0?-1:a-b;}):[];
